"""Reward-variance CALIBRATION - inference only, NO training. Samples completions from the
BASE model on candidate boundary tasks at training temperature, scores them with the real
verifier, and reports the reward DISTRIBUTION per task. This directly measures the precondition
the local sim cannot: does THIS real model produce reward variance on THIS task. All-0 = too
hard; all-1 = too easy; a SPREAD = a confirmed boundary task (training will have gradient)."""
import base64, io, sys, tarfile

_PKG_B64 = ""
tarfile.open(fileobj=io.BytesIO(base64.b64decode(_PKG_B64)), mode="r:gz").extractall("/tmp/fr")
sys.path.insert(0, "/tmp/fr")

from flightrecorder.repro.reward_testhack import train_reward, CodeTask  # noqa: E402
import numpy as np  # noqa: E402
import torch  # noqa: E402
from transformers import AutoModelForCausalLM, AutoTokenizer  # noqa: E402

MODEL = "Qwen/Qwen2.5-1.5B"   # BASE (not Instruct)
N = 48
TEMP = 1.0
MAXTOK = 200
BATCH = 24


def _task(name, prompt, cases):
    tests = "import submission\n" + "".join(
        f"def test_{i}(): assert submission.solve({a!r}) == {b!r}\n" for i, (a, b) in enumerate(cases))
    return {"name": name, "prompt": prompt, "tests": tests}


TASKS = [
    _task("sum_to_n",
          "# Write solve(n) returning the sum of integers from 1 to n.\ndef solve(n):\n",
          [(1, 1), (2, 3), (3, 6), (5, 15), (10, 55), (0, 0), (7, 28), (100, 5050)]),
    _task("count_vowels",
          "# Write solve(s) returning the number of lowercase vowels (a,e,i,o,u) in s.\ndef solve(s):\n",
          [("hello", 2), ("world", 1), ("aeiou", 5), ("xyz", 0), ("banana", 3), ("rhythm", 0),
           ("queue", 4), ("", 0)]),
    _task("lus2",
          "# Write solve(s): length of the longest substring of s with at most two distinct characters.\ndef solve(s):\n",
          [("a", 1), ("abaccc", 4), ("aabbcc", 4), ("abcabc", 2), ("aaaa", 4), ("eceba", 3),
           ("ccaabbb", 5)]),
]


def truncate(prompt, cont):
    lines = (prompt + cont).split("\n")
    out, started = [], False
    for ln in lines:
        if ln.startswith("def solve"):
            out.append(ln); started = True; continue
        if not started:
            out.append(ln); continue
        if ln.strip() == "" or ln[:1] in (" ", "\t"):
            out.append(ln)
        else:
            break
    return "\n".join(out) + "\n"


def hist(rs):
    b = [0] * 6  # ==0, (0,.25), [.25,.5), [.5,.75), [.75,1), ==1
    for r in rs:
        b[0 if r == 0 else 5 if r == 1 else 1 if r < .25 else 2 if r < .5 else 3 if r < .75 else 4] += 1
    return b


tok = AutoTokenizer.from_pretrained(MODEL)
if tok.pad_token is None:
    tok.pad_token = tok.eos_token
model = AutoModelForCausalLM.from_pretrained(MODEL, dtype=torch.float16).to("cuda").eval()

print(f"CALIBRATION  model={MODEL}  N={N}  temp={TEMP}", flush=True)
for t in TASKS:
    enc = tok(t["prompt"], return_tensors="pt").to(model.device)
    rs = []
    for b in range(0, N, BATCH):
        k = min(BATCH, N - b)
        with torch.no_grad():
            out = model.generate(**enc, do_sample=True, temperature=TEMP, top_p=0.95,
                                  max_new_tokens=MAXTOK, num_return_sequences=k,
                                  pad_token_id=tok.eos_token_id)
        for seq in out:
            cont = tok.decode(seq[enc["input_ids"].shape[1]:], skip_special_tokens=True)
            sub = truncate(t["prompt"], cont)
            task = CodeTask(prompt=t["prompt"], visible_tests=t["tests"], hidden_tests=t["tests"], name=t["name"])
            try:
                rs.append(float(train_reward(sub, task)))
            except Exception:
                rs.append(0.0)
    arr = np.array(rs)
    q = [round(float(x), 3) for x in np.quantile(arr, [.1, .25, .5, .75, .9])]
    print(f"\n### TASK {t['name']}  n={len(rs)}", flush=True)
    print(f"  mean={arr.mean():.3f} std={arr.std():.3f} min={arr.min():.3f} max={arr.max():.3f}", flush=True)
    print(f"  quantiles[10/25/50/75/90]={q}", flush=True)
    print(f"  frac==0={(arr == 0).mean():.2f}  frac==1={(arr == 1).mean():.2f}", flush=True)
    print(f"  hist[==0,(0,.25),[.25,.5),[.5,.75),[.75,1),==1]={hist(rs)}", flush=True)
print("\nCALIBRATION DONE", flush=True)
